{
  "implementation": "import heapq

def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    total = sum(allocations)
    capacities = [seg['capacity'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    heap = []
    for i in range(n):
        if allocations[i] < capacities[i]:
            priority = importances[i] / (allocations[i] + 1)
            heapq.heappush(heap, (-priority, i))
    while total < budget and heap:
        neg_priority, i = heapq.heappop(heap)
        if allocations[i] >= capacities[i]:
            continue
        allocations[i] += 1
        total += 1
        if allocations[i] < capacities[i]:
            new_priority = importances[i] / (allocations[i] + 1)
            heapq.heappush(heap, (-new_priority, i))
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
}
